impl FilePrompt {
    fn append(&mut self, text: &str) {
        for ch in text.chars().filter(|c| !c.is_control()) {
            if self.text.len() + ch.len_utf8() > 1024 {
                break;
            }
            self.text.push(ch);
        }
    }
}
impl RemotePrompt {
    fn text_mut(&mut self) -> &mut String {
        if self.host_field {
            &mut self.host_id
        } else {
            &mut self.ssh
        }
    }
    fn append(&mut self, text: &str) {
        let target = self.text_mut();
        for c in text.chars().filter(|c| !c.is_control()) {
            if target.len() + c.len_utf8() > 256 {
                break;
            }
            target.push(c);
        }
    }
}
