struct BoundedWorkerPermit(Arc<AtomicUsize>);
impl BoundedWorkerPermit {
    fn acquire(active: &Arc<AtomicUsize>) -> Option<Self> {
        active.try_update(Ordering::AcqRel, Ordering::Acquire, |count| {
            (count < 4).then_some(count + 1)
        }).ok().map(|_| Self(active.clone()))
    }
}
impl Drop for BoundedWorkerPermit {
    fn drop(&mut self) { self.0.fetch_sub(1, Ordering::Release); }
}
