/// Status for `:e` of a new file whose folder does not exist yet.
const NEW_FILE_MISSING_FOLDER: &str = "Archivo nuevo · la carpeta no existe; :w no la crea";
/// Spanish cause for a storage::initialize error (its messages are internal
/// and partly English). The original text is kept, bounded, when unknown.
fn storage_failure_cause(error: &str) -> String {
    match error {
        "Unsafe project registry" => {
            "projects.json no es un archivo regular único (symlink, enlace duro o más de 32 KiB)".into()
        }
        "Project registry too large" => "projects.json supera 32 KiB".into(),
        "Invalid explicit project registry" => {
            "projects.json tiene rutas relativas o más de 128 workspaces".into()
        }
        _ if error.starts_with("El directorio de estado") => error.into(),
        _ => {
            let detail: String = workspace_app::text_safety::strip_bidi(error)
                .lines()
                .next()
                .unwrap_or_default()
                .chars()
                .take(120)
                .collect();
            format!("no se pudo leer el directorio de estado o projects.json ({detail})")
        }
    }
}
/// Shorten `text` to at most `max_chars` characters, ending with an ellipsis.
fn fit_status_text(text: &str, max_chars: usize) -> String {
    if text.chars().count() <= max_chars {
        return text.to_owned();
    }
    let keep = max_chars.saturating_sub(1).max(1);
    let mut out: String = text.chars().take(keep).collect();
    out.push('…');
    out
}

/// A multi-line paste replayed from a queue is held, never prompted: a
/// queued Enter would confirm it unseen. Nothing reached the PTY. When input
/// typed after it is still held, the queue must be discarded first.
fn held_paste_message(lines: usize, input_follows: bool) -> String {
    let what = if lines == 1 { "1 línea".to_string() } else { format!("{lines} líneas") };
    if input_follows {
        format!("Pegado de {what} retenido; no se envió nada · la entrada siguiente quedó en espera: Revisar → Descartar y seguir, y pegá de nuevo")
    } else {
        format!("Pegado de {what} retenido; no se envió nada · pegá de nuevo para confirmar")
    }
}
/// Spanish message for a storage::remember error.
fn remember_failure_message(error: &str) -> String {
    match error {
        "Invalid explicit project registry" => {
            "La lista de workspaces llegó al límite de 128; este cambio no se recordó · olvidá uno con Alt+d en Space f p".into()
        }
        "Project registry too large" => {
            "La lista de workspaces supera 32 KiB; este cambio no se recordó · olvidá uno con Alt+d en Space f p".into()
        }
        _ => {
            let detail: String = workspace_app::text_safety::strip_bidi(error)
                .lines()
                .next()
                .unwrap_or_default()
                .chars()
                .take(120)
                .collect();
            format!("No se pudo guardar la lista de workspaces: {detail}")
        }
    }
}
